    #include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>

// Simple stack implementation
#define MAX 1000
int st[MAX];
int top = -1;

void push(int x) {
    st[++top] = x;
}

int pop() {
    return st[top--];
}

int floorDiv(int a, int b) {
    if (a * b < 0 && a % b != 0)
        return (a / b) - 1;
    return a / b;
}

int evaluatePrefix(char* arr[], int n) {
    // Traverse from right to left
    for (int i = n - 1; i >= 0; i--) {
        char* token = arr[i];

        // If it's an operand (number), push it onto the stack
        if (isdigit(token[0]) || (strlen(token) > 1 && token[0] == '-')) {
            push(atoi(token));
        }
        // Otherwise, it must be an operator
        else {
            int val1 = pop();
            int val2 = pop();

            if (strcmp(token, "+") == 0) {
                push(val1 + val2);
            } else if (strcmp(token, "-") == 0) {
                push(val1 - val2);
            } else if (strcmp(token, "*") == 0) {
                push(val1 * val2);
            } else if (strcmp(token, "/") == 0) {
                push(floorDiv(val1, val2));
            } else if (strcmp(token, "^") == 0) {
                push((int)pow(val1, val2));
            }
        }
    }
    return pop();
}

int main() {
    char* arr[] = {"+", "*", "/", "+", "100", "200", "2", "5", "7"};
    int n = sizeof(arr) / sizeof(arr[0]);
    printf("%d\n", evaluatePrefix(arr, n));
    return 0;
}


            Java

    import java.util.Stack;

public class GFG {

    static int floorDiv(int a, int b) {
        if (a * b < 0 && a % b != 0)
            return (a / b) - 1;
        return a / b;
    }

    public static int evaluatePrefix(String[] arr) {
        Stack<Integer> st = new Stack<>();
        int n = arr.length;

        // Traverse from right to left
        for (int i = n - 1; i >= 0; i--) {
            String token = arr[i];

            // If it's an operand (number), push it onto the stack
            if (Character.isDigit(token.charAt(0)) || 
               (token.length() > 1 && token.charAt(0) == '-')) {
                st.push(Integer.parseInt(token));
            }
            // Otherwise, it must be an operator
            else {
                int val1 = st.pop();
                int val2 = st.pop();

                if (token.equals("+")) {
                    st.push(val1 + val2);
                } else if (token.equals("-")) {
                    st.push(val1 - val2);
                } else if (token.equals("*")) {
                    st.push(val1 * val2);
                } else if (token.equals("/")) {
                    st.push(floorDiv(val1, val2));
                } else if (token.equals("^")) {
                    st.push((int)Math.pow(val1, val2));
                }
            }
        }
        return st.pop();
    }

    public static void main(String[] args) {
        String[] arr = {"+", "*", "/", "+", "100", "200", "2", "5", "7"};
        System.out.println(evaluatePrefix(arr));
    }
}


