            JavaScript

    function evaluatePrefix(arr) {
    let st = [];
    let n = arr.length;

    // Traverse from right to left
    for (let i = n - 1; i >= 0; i--) {
        let token = arr[i];

        // If it's an operand (number), push it onto the stack
        if (!isNaN(token) && token.length > 0) {
            st.push(parseInt(token));
        }

        // Otherwise, it must be an operator
        else {
            let val1 = st.pop();
            let val2 = st.pop();

            if (token === "+") {
                st.push(val1 + val2);
            } else if (token === "-") {
                st.push(val1 - val2);
            } else if (token === "*") {
                st.push(val1 * val2);
            } else if (token === "/") {
                st.push(Math.floor(val1 / val2)); 
            } else if (token === "^") {
                st.push(Math.pow(val1, val2));
            }
        }
    }
    return st.pop();
}

